mapper.select:
SELECT o.*, s.supplier_name, w.warehouse_name, u1.real_name as applicant_name, u2.real_name as approver_name, d.dept_name FROM biz_purchase_order o LEFT JOIN biz_supplier s ON o.supplier_id = s.id LEFT JOIN biz_warehouse w ON o.warehouse_id = w.id LEFT JOIN sys_user u1 ON o.applicant_id = u1.id LEFT JOIN sys_user u2 ON o.approver_id = u2.id LEFT JOIN sys_dept d ON o.dept_id = d.id WHERE o.deleted = 0
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.supplier_id = #{supplierId}
AND o.status = #{status}
AND o.dept_id = #{deptId}
ORDER BY o.apply_time DESC

SELECT COUNT(*)
FROM biz_purchase_order
WHERE deleted = 0 AND status = #{status}
